```js
// app.js
const express = require('express');
const session = require('express-session');
const { rateLimit } = require('express-rate-limit');
const argon2 = require('argon2');

if (!process.env.SESSION_SECRET) throw new Error('SESSION_SECRET not set');

const app = express();
// Uncomment only when behind exactly one reverse proxy; otherwise clients can spoof their IP.
// app.set('trust proxy', 1);
app.use(express.json({ limit: '10kb' }));

app.use(session({
  name: 'sid',
  secret: process.env.SESSION_SECRET,
  resave: false,
  saveUninitialized: false,
  cookie: {
    httpOnly: true,
    secure: process.env.NODE_ENV === 'production',
    sameSite: 'lax',
    maxAge: 8 * 60 * 60 * 1000,
  },
}));

// Demo store. Replace with a database.
const users = new Map(); // username -> { id, username, hash }
let nextId = 1;

// Verified when the username is unknown, so response time does not reveal which usernames exist.
const dummyHash = argon2.hash('dummy-password');

// Counts only failed responses (status >= 400).
const failLimiter = (options) => rateLimit({
  windowMs: 15 * 60 * 1000,
  skipSuccessfulRequests: true,
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many failed attempts. Try again later.' },
  ...options,
});
const perIp = failLimiter({ limit: 20 });
const perUser = failLimiter({
  limit: 5,
  keyGenerator: (req) => String(req.body?.username ?? '').toLowerCase(),
});

function readCredentials(req, res) {
  const { username, password } = req.body ?? {};
  if (typeof username !== 'string' || typeof password !== 'string' ||
      !username || password.length < 8 || password.length > 1024) {
    res.status(400).json({ error: 'username and password (8-1024 chars) required' });
    return null;
  }
  return { username: username.toLowerCase(), password };
}

function requireAuth(req, res, next) {
  if (!req.session.userId) return res.status(401).json({ error: 'Not logged in' });
  next();
}

app.post('/register', perIp, async (req, res) => {
  const creds = readCredentials(req, res);
  if (!creds) return;
  if (users.has(creds.username)) return res.status(409).json({ error: 'Username taken' });
  const hash = await argon2.hash(creds.password); // argon2id, salt included
  users.set(creds.username, { id: nextId++, username: creds.username, hash });
  res.status(201).json({ ok: true });
});

app.post('/login', perIp, perUser, async (req, res, next) => {
  const creds = readCredentials(req, res);
  if (!creds) return;
  const user = users.get(creds.username);
  const ok = await argon2.verify(user ? user.hash : await dummyHash, creds.password);
  if (!user || !ok) return res.status(401).json({ error: 'Invalid credentials' });

  // New session ID on login prevents session fixation.
  req.session.regenerate((err) => {
    if (err) return next(err);
    req.session.userId = user.id;
    res.json({ ok: true });
  });
});

app.post('/logout', (req, res, next) => {
  req.session.destroy((err) => {
    if (err) return next(err);
    res.clearCookie('sid');
    res.json({ ok: true });
  });
});

app.get('/me', requireAuth, (req, res) => {
  res.json({ userId: req.session.userId });
});

app.listen(process.env.PORT || 3000);
```

Run: `SESSION_SECRET=$(openssl rand -hex 32) node app.js`

Limits: 5 failures per username and 20 per IP, per 15 minutes. Successful logins do not count.

Before production:

- **Stores:** Sessions and rate-limit counters live in process memory. They reset on restart and are not shared across instances. Use Redis (`connect-redis`, `rate-limit-redis`).
- **Lockout:** The per-username limit lets an attacker lock a victim out for 15 minutes with 5 bad guesses. Raise the limit or key on username plus IP if that matters more than slowing distributed guessing.
- **Enumeration:** `/register` returns 409 for taken usernames, which reveals which accounts exist.
- **HTTPS:** The `secure` cookie needs HTTPS. Behind a TLS-terminating proxy, enable the `trust proxy` line or the cookie is never set.
